cat >/root/fix_wwwroot.php <<'PHP'
<?php
$cfgFile = file_exists('/app/moodle/config.php') ? '/app/moodle/config.php' : '/var/www/html/moodle/config.php';
$url = getenv('FIX_URL');
$src = @file_get_contents($cfgFile);
if ($src === false) { fwrite(STDERR, "Cannot read $cfgFile\n"); exit(1); }
if (preg_match('/\$CFG->wwwroot\s*=\s*[\'\"][^\'\"]+[\'\"];?/', $src)) {
  $src = preg_replace('/\$CFG->wwwroot\s*=\s*[\'\"][^\'\"]+[\'\"];?/', '$CFG->wwwroot = "'.$url.'";', $src, 1);
} else {
  $src .= PHP_EOL.'$CFG->wwwroot = "'.$url.'";'.PHP_EOL;
}
if (@file_put_contents($cfgFile, $src) === false) { fwrite(STDERR, "Cannot write $cfgFile\n"); exit(2); }
echo "Updated wwwroot in $cfgFile to $url\n";
?>
PHP
